package main

import (
	"fmt"
	"sync"
)

type Counter struct {
	mu    sync.Mutex
	value int
}

func (c *Counter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.value++
}

func (c *Counter) Value() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.value
}

func main() {
	counter := &Counter{}
	var wg sync.WaitGroup
	for range 100 {
		wg.Go(counter.Inc)
	}
	wg.Wait()
	fmt.Println(counter.Value())
}
```
Both mutation and observation use the same Mutex. The zero-value Counter is usable, and callers share its pointer rather than copying it.

```go
package main

import (
	"errors"
	"fmt"
	"sync"
)

type Ledger struct {
	mu       sync.Mutex
	balances map[string]int
}

func (l *Ledger) Transfer(from, to string, amount int) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if amount <= 0 || l.balances[from] < amount {
		return errors.New("invalid transfer")
	}
	l.balances[from] -= amount
	l.balances[to] += amount
	return nil
}

func (l *Ledger) Balance(name string) int {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.balances[name]
}

func main() {
	ledger := &Ledger{balances: map[string]int{"A": 100, "B": 0}}
	if err := ledger.Transfer("A", "B", 30); err != nil {
		panic(err)
	}
	fmt.Println(ledger.Balance("A"), ledger.Balance("B"))
}
```
Validation and both balance updates are one transition. No external call occurs while the ledger lock is held.

```go
package main

import (
	"fmt"
	"sync"
)

type Cache struct {
	mu   sync.Mutex
	data map[string]int
}

func NewCache() *Cache {
	return &Cache{data: make(map[string]int)}
}

func (c *Cache) Put(key string, value int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.data[key] = value
}

func (c *Cache) Snapshot() map[string]int {
	c.mu.Lock()
	defer c.mu.Unlock()
	copy := make(map[string]int, len(c.data))
	for key, value := range c.data {
		copy[key] = value
	}
	return copy
}

func main() {
	cache := NewCache()
	cache.Put("ready", 1)
	fmt.Println(cache.Snapshot()["ready"])
}
```
The pointer preserves one lock identity, and Snapshot prevents the protected map from escaping after Unlock.
